function spawnEnemy(){let ranged=save.stage>=4&&Math.random()<Math.min(.62,.24+save.stage*.012);let type=ranged?'ranged':'melee';let max=5+Math.floor(save.stage*.34);if(waveSpawned>=max)return;let lane=(Math.random()*.76+.12);enemies.push({x:lane,z:0.08+Math.random()*.04,type,hp:1+Math.floor((save.stage-1)/8),maxHp:1+Math.floor((save.stage-1)/8),attack:1.6+Math.random()*1.8,flash:0,seed:Math.random()*10,dead:false});waveSpawned++}
function stageEnemyMax(){return 5+Math.floor(save.stage*.34)}
function drawBackground(w,h){let sky=ctx.createLinearGradient(0,0,0,h*.72);sky.addColorStop(0,'#1c302c');sky.addColorStop(.6,'#71806a');sky.addColorStop(1,'#c28d5e');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
 let sunX=w*.69,sunY=h*.31;let glow=ctx.createRadialGradient(sunX,sunY,5,sunX,sunY,h*.25);glow.addColorStop(0,'#e6bb7c88');glow.addColorStop(1,'#e6bb7c00');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h*.7);ctx.fillStyle='#e2b477';ctx.beginPath();ctx.arc(sunX,sunY,Math.min(w,h)*.055,0,Math.PI*2);ctx.fill();
 ctx.fillStyle='#526553';ctx.beginPath();ctx.moveTo(0,h*.57);ctx.lineTo(w*.08,h*.42);ctx.lineTo(w*.2,h*.54);ctx.lineTo(w*.37,h*.39);ctx.lineTo(w*.54,h*.56);ctx.lineTo(w*.73,h*.42);ctx.lineTo(w*.88,h*.55);ctx.lineTo(w,h*.4);ctx.lineTo(w,h*.73);ctx.lineTo(0,h*.73);ctx.fill();
 for(let side of [0,1])for(let i=0;i<9;i++){let depth=(i+1)/9,x=side? w*(.76+depth*.3):w*(.24-depth*.3),base=h*(.57+depth*.14),size=(.035+depth*.15)*h;ctx.fillStyle=i%2?'#25392b':'#304631';ctx.beginPath();ctx.moveTo(x,base-size);ctx.lineTo(x-size*.55,base);ctx.lineTo(x+size*.55,base);ctx.fill();ctx.fillRect(x-size*.06,base-size*.18,size*.12,size*.22)}
 let ground=ctx.createLinearGradient(0,h*.58,0,h);ground.addColorStop(0,'#5b6146');ground.addColorStop(.35,'#454a36');ground.addColorStop(1,'#19251d');ctx.fillStyle=ground;ctx.beginPath();ctx.moveTo(w*.39,h*.58);ctx.lineTo(w*.61,h*.58);ctx.lineTo(w*1.35,h);ctx.lineTo(-w*.35,h);ctx.fill();
 ctx.strokeStyle='#c2a87626';ctx.lineWidth=1;for(let i=0;i<8;i++){let y=h*(.6+i*i*.006);ctx.beginPath();ctx.moveTo(w*.4-(y-h*.58)*1.5,y);ctx.lineTo(w*.6+(y-h*.58)*1.5,y);ctx.stroke()}for(let i=0;i<6;i++){let x=w*(.4+i*.04);ctx.beginPath();ctx.moveTo(x,h*.58);ctx.lineTo((x-w*.5)*2+w*.5,h);ctx.stroke()}
 // foliage framing
 for(let side=0;side<2;side++){ctx.fillStyle='#17251d';ctx.beginPath();ctx.moveTo(side? w:0,0);ctx.lineTo(side?w*.89:w*.11,0);ctx.lineTo(side?w*.98:w*.02,h*.38);ctx.lineTo(side?w*.88:w*.12,h*.31);ctx.lineTo(side?w*.96:w*.04,h*.55);ctx.lineTo(side?w*.82:w*.18,h*.43);ctx.lineTo(side?w*.9:w*.1,h*.68);ctx.lineTo(side?w*.76:w*.24,h*.5);ctx.lineTo(side?w*.78:w*.22,h*.2);ctx.closePath();ctx.fill()}
}
function drawEnemy(e,w,h){let perspective=.22+e.z*1.72,scale=perspective, x=e.x*w, groundY=h*(.60+e.z*.36),bodyH=h*.17*scale,bodyW=bodyH*(e.type==='ranged'?.68:.75),bob=Math.sin(frame*.006+e.seed)*bodyH*.025;ctx.save();ctx.translate(x,groundY+bob);ctx.scale(scale,scale);let dark=e.type==='ranged'?'#392c30':'#26382b',mid=e.type==='ranged'?'#765148':'#64794f';
 ctx.fillStyle='#11181077';ctx.beginPath();ctx.ellipse(0,0,bodyW*.72,bodyW*.2,0,0,Math.PI*2);ctx.fill();
 // legs
 ctx.fillStyle=dark;ctx.fillRect(-bodyW*.34,-bodyH*.31,bodyW*.25,bodyH*.34);ctx.fillRect(bodyW*.11,-bodyH*.31,bodyW*.25,bodyH*.34);ctx.strokeStyle=mid;ctx.lineWidth=bodyW*.12;ctx.beginPath();ctx.moveTo(-bodyW*.22,-bodyH*.18);ctx.lineTo(-bodyW*.25,-bodyH*.02);ctx.moveTo(bodyW*.22,-bodyH*.18);ctx.lineTo(bodyW*.26,-bodyH*.02);ctx.stroke();
 // torso
 ctx.fillStyle=dark;ctx.beginPath();ctx.moveTo(-bodyW*.42,-bodyH*.34);ctx.lineTo(-bodyW*.32,-bodyH*.76);ctx.lineTo(-bodyW*.16,-bodyH*.82);ctx.lineTo(bodyW*.2,-bodyH*.8);ctx.lineTo(bodyW*.38,-bodyH*.35);ctx.closePath();ctx.fill();ctx.fillStyle=mid;ctx.beginPath();ctx.ellipse(0,-bodyH*.58,bodyW*.27,bodyH*.24,0,0,Math.PI*2);ctx.fill();
 // head, horns
 ctx.fillStyle=e.type==='ranged'?'#a27662':'#8c9565';ctx.beginPath();ctx.arc(0,-bodyH*.91,bodyW*.22,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ded1a0';ctx.beginPath();ctx.moveTo(-bodyW*.15,-bodyH*1.01);ctx.lineTo(-bodyW*.35,-bodyH*1.25);ctx.lineTo(-bodyW*.08,-bodyH*1.13);ctx.fill();ctx.beginPath();ctx.moveTo(bodyW*.15,-bodyH*1.01);ctx.lineTo(bodyW*.33,-bodyH*1.22);ctx.lineTo(bodyW*.08,-bodyH*1.12);ctx.fill();ctx.fillStyle='#edbd68';ctx.fillRect(-bodyW*.12,-bodyH*.93,bodyW*.07,bodyH*.035);ctx.fillRect(bodyW*.06,-bodyH*.93,bodyW*.07,bodyH*.035);
 // arms and weapon
 ctx.strokeStyle=dark;ctx.lineWidth=bodyW*.16;ctx.beginPath();ctx.moveTo(-bodyW*.27,-bodyH*.68);ctx.lineTo(-bodyW*.48,-bodyH*.46);ctx.lineTo(-bodyW*.54,-bodyH*.27);ctx.moveTo(bodyW*.26,-bodyH*.68);ctx.lineTo(bodyW*.48,-bodyH*.47);ctx.lineTo(bodyW*.53,-bodyH*.26);ctx.stroke();if(e.type==='ranged'){ctx.strokeStyle='#c6ad72';ctx.lineWidth=bodyW*.035;ctx.beginPath();ctx.arc(bodyW*.54,-bodyH*.47,bodyW*.23,-1.2,1.2);ctx.stroke()}else{ctx.fillStyle='#a99a71';ctx.fillRect(bodyW*.45,-bodyH*.33,bodyW*.1,bodyH*.35)}
 if(e.hp<e.maxHp){ctx.fillStyle='#1b211a';ctx.fillRect(-bodyW*.4,-bodyH*1.35,bodyW*.8,bodyH*.07);ctx.fillStyle='#d4865f';ctx.fillRect(-bodyW*.4,-bodyH*1.35,bodyW*.8*(e.hp/e.maxHp),bodyH*.07)}ctx.restore()}
function drawBow(w,h){let x=w*.5,y=h*1.03,scale=Math.min(w/900,h/600);ctx.save();ctx.translate(x,y);let pull=charging?clamp((performance.now()-chargeStart)/3000,0,1):0;let sway=Math.sin(frame*.0017)*2*scale;ctx.translate(sway,0);ctx.strokeStyle=save.skin?'#ddbb70':'#856445';ctx.lineWidth=7*scale;ctx.beginPath();ctx.moveTo(-w*.18,-h*.23);ctx.quadraticCurveTo(-w*.07,-h*(.5+pull*.12),0,-h*.35);ctx.quadraticCurveTo(w*.07,-h*(.5+pull*.12),w*.18,-h*.23);ctx.stroke();ctx.strokeStyle='#e4d7b8';ctx.lineWidth=1.5*scale;ctx.beginPath();ctx.moveTo(-w*.18,-h*.23);ctx.lineTo(0,-h*(.31+pull*.11));ctx.lineTo(w*.18,-h*.23);ctx.stroke();ctx.strokeStyle='#d0b77a';ctx.lineWidth=2*scale;ctx.beginPath();ctx.moveTo(0,-h*(.32+pull*.1));ctx.lineTo(0,-h*.48);ctx.stroke();ctx.fillStyle='#33271e';ctx.beginPath();ctx.moveTo(-w*.045,0);ctx.lineTo(-w*.026,-h*.2);ctx.lineTo(w*.03,-h*.2);ctx.lineTo(w*.055,0);ctx.fill();ctx.restore()}
function draw(){let r=world.getBoundingClientRect(),w=r.width,h=r.height;if(!w||!h)return;ctx.clearRect(0,0,w,h);drawBackground(w,h);for(let e of enemies.slice().sort((a,b)=>a.z-b.z))drawEnemy(e,w,h);drawBow(w,h);
 // arrows streaks and particles
 for(let p of particles){ctx.globalAlpha=clamp(p.life,0,1);if(p.kind==='arrow'){ctx.strokeStyle='#efcf86';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x*w,p.y*h);ctx.lineTo((p.x-p.vx*.035)*w,(p.y-p.vy*.035)*h);ctx.stroke()}else{ctx.fillStyle=p.color||'#e4bd70';ctx.beginPath();ctx.arc(p.x*w,p.y*h,p.size||2,0,Math.PI*2);ctx.fill()}}ctx.globalAlpha=1;
 // incoming ranged projectiles
 for(let e of enemies)if(e.bolt>0){let t=clamp(1-e.bolt/1.1,0,1),x=e.x*w+(pointer.x-.5)*t*w*.6,y=h*(.62-t*.43);ctx.strokeStyle='#df8061';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-8*t,y-9*t);ctx.lineTo(x+8*t,y+9*t);ctx.stroke()}}
function setAim(ev){let rect=world.getBoundingClientRect();pointer.x=clamp((ev.clientX-rect.left)/rect.width,0,1);pointer.y=clamp((ev.clientY-rect.top)/rect.height,0,1);let a=$('#aimVisual');a.style.left=`${pointer.x*100}%`;a.style.top=`${pointer.y*100}%`}
world.addEventListener('pointermove',setAim);world.addEventListener('pointerdown',e=>{if(state!=='game'||$('#resultOverlay').classList.contains('show'))return;e.preventDefault();world.setPointerCapture?.(e.pointerId);setAim(e);if(!charging){charging=true;chargeStart=performance.now();$('#gameHint').textContent='시위를 당기는 중… 놓으면 발사';$('#chargeName').textContent='DRAWING';}});world.addEventListener('pointerup',e=>{if(charging){let time=(performance.now()-chargeStart)/1000;charging=false;fireArrow(time);$('#gameHint').textContent='화면을 누르고 있으면 활을 당깁니다';$('#chargeName').textContent='BOW DRAW'}});world.addEventListener('pointercancel',()=>{if(charging){let t=(performance.now()-chargeStart)/1000;charging=false;fireArrow(t)}});
function fireArrow(sec){if(attackCooldown>0)return;sec=clamp(sec,0,3);let tier=Math.min(3,Math.floor(sec+1e-4)),damage=(1+tier*.78)*(1+save.upgrade*.2+(save.skin?.15:0));if(performance.now()<skillUntil)damage*=1.65;let pierce=tier>=3,accuracy=.055+(.23*(1-sec/3));if(pierce)accuracy=.07;let shotX=pointer.x,shotY=pointer.y;particles.push({kind:'arrow',x:.5,y:.83,vx:shotX-.5,vy:shotY-.83,life:.36});attackCooldown=.24;let hit=[];let candidates=enemies.filter(e=>!e.dead).map(e=>{let py=.60+e.z*.36-.17*(.22+e.z*1.72),px=e.x;let dx=(px-shotX)*(world.clientWidth/world.clientHeight),dy=py-shotY;let radius=accuracy+e.z*.09;return {e,dist:Math.hypot(dx,dy),radius}}).filter(c=>c.dist<c.radius).sort((a,b)=>a.e.z-b.e.z);
 if(pierce){for(let c of candidates)hit.push(c.e)}else if(candidates.length)hit.push(candidates[candidates.length-1].e);
 for(let e of hit){e.hp-=damage;e.flash=.16;for(let i=0;i<7;i++)particles.push({kind:'spark',x:e.x,y:.6+e.z*.36-.13,color:'#e6c17b',life:.5+Math.random()*.4,size:2+Math.random()*2});if(e.hp<=0)killEnemy(e)}if(!hit.length)toast(pierce?'관통 화살 — 명중 없음':`빗나감 · ${tier}단계 발사`);else toast(pierce?`관통 화살! ${hit.length}체 관통`:`명중! ${tier}단계 · ${Math.round(damage)} 피해`);$('#chargeFill').style.width='0%';if(enemies.every(e=>e.dead)&&waveSpawned>=stageEnemyMax())finishStage(true)}
function killEnemy(e){if(e.dead)return;e.dead=true;killsThisStage++;save.kills++;let reward=8+Math.floor(save.stage*.65)+(e.type==='ranged'?3:0);save.gold+=reward;persist();for(let i=0;i<12;i++)particles.push({kind:'spark',x:e.x+(Math.random()-.5)*.08,y:.65+e.z*.31,color:i%2?'#d7aa58':'#c8795d',life:.65+Math.random()*.4,size:2+Math.random()*3});toast(`처치 +${reward} G`)}
function activateSkill(){if(!save.skill||skillUntil>performance.now())return;skillUntil=performance.now()+8000;$('#skillBtn').disabled=true;toast('집중의 숨결 · 8초간 공격력 상승');setTimeout(()=>{if(state==='game')$('#skillBtn').disabled=false},8000)}$('#skillBtn').onclick=activateSkill;
$('#returnBtn').onclick=()=>{$('#resultOverlay').classList.remove('show');$('#game').classList.remove('active');$('#lobby').classList.add('active');state='lobby';persist();refreshLobby()};
function finishStage(won){if(state!=='game'||$('#resultOverlay').classList.contains('show'))return;charging=false;state='result';let bonus=won?24+save.stage*3:8+Math.floor(killsThisStage*3);save.gold+=bonus;resultReward=bonus;persist();$('#resultKicker').textContent=won?'HUNT COMPLETE':'HUNT FAILED';$('#resultTitle').textContent=won?'사냥 성공':'사냥 실패';$('#resultText').textContent=won?`${chapters[Math.ceil(save.stage/3)-1]}의 위협을 잠재웠습니다. 다음 사냥을 준비하세요.`:`숲은 아직 위험합니다. 처치한 적의 전리품은 챙겼습니다.`;$('#rewardText').innerHTML=`전리품 <b>+ ${bonus} G</b>　 ·　 처치 ${killsThisStage}마리`;$('#returnBtn').textContent=won?'전리품을 챙겨 로비로':'다시 정비하러 로비로';$('#resultOverlay').classList.add('show');if(won&&save.stage<30)save.stage++;persist()}

