 for(let e of enemies){if(e.dead)continue;e.flash=Math.max(0,e.flash-dt);if(e.type==='melee'){e.z+=dt*(.055+save.stage*.0019);if(e.z>.91){e.dead=true;health-=16;toast('근접 적의 습격!')}}else{e.z+=dt*(.025+save.stage*.0008);e.attack-=dt;if(e.attack<=0&&e.z>.18){e.bolt=1.1;e.attack=2.7+Math.random()*1.5}if(e.bolt>0){e.bolt-=dt;if(e.bolt<=0){health-=9;toast('원거리 공격에 피격!')}}} }
